[
  {
    "id": "take_cart_on_entry",
    "text": "A shopper must not go north from the entrance cart area at (1,7) unless they already have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(1,7)",
          "N",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "obtain_cart_once",
    "text": "Every shopping trip is obliged to obtain a cart at least once.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cart_in_north_aisle",
    "text": "Carts are prohibited in the north aisle cells at (3,1) and (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_push_cart_north_from_33",
    "text": "A shopper must not push a cart north from cell (3,3).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "no_shelf_interaction_with_cart",
    "text": "A shopper is prohibited from interacting at shelf cell (3,1) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_item",
    "text": "After interacting at item cell (3,1), the shopper is obliged to return to cell (3,3) with a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "dont_leave_33_south_without_cart",
    "text": "A shopper must not leave cell (3,3) to the south unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "S",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
